/*
 * Locates the region written by the author in the compose editor body: all
 * top-level children except the quote, signature and forward container
 * generated by Thunderbird.
 */
(function (root) {
  "use strict";

  const EXCLUDED_SELECTOR = [
    ".moz-cite-prefix",
    "blockquote[type=\"cite\"]",
    ".moz-signature",
    ".moz-forward-container",
    ".moz-email-headers-table",
  ].join(",");

  function isExcluded(node) {
    return node.nodeType === 1 && node.matches(EXCLUDED_SELECTOR);
  }

  function isBlankText(node) {
    return node.nodeType === 3 && !node.nodeValue.trim();
  }

  /**
   * Returns the top-level nodes of the author region, in document order.
   * Whitespace-only text nodes are ignored; empty elements (<br>, <p><br></p>)
   * are included because they mark the cursor position in replies.
   */
  function findAuthorRegion(body) {
    const nodes = [];
    for (const node of body.childNodes) {
      if (isExcluded(node) || isBlankText(node)) {
        continue;
      }
      if (node.nodeType === 1 || node.nodeType === 3) {
        nodes.push(node);
      }
    }
    return nodes;
  }

  /**
   * Replaces the author region with `replacement` (node or DocumentFragment).
   * If the region is empty the content goes at the top of the body.
   */
  function replaceAuthorRegion(body, replacement) {
    const nodes = findAuthorRegion(body);
    if (nodes.length === 0) {
      body.insertBefore(replacement, body.firstChild);
      return;
    }
    const first = nodes[0];
    body.insertBefore(replacement, first);
    for (const node of nodes) {
      node.remove();
    }
  }

  root.ThunderMD = Object.assign(root.ThunderMD || {}, {
    EXCLUDED_SELECTOR,
    findAuthorRegion,
    replaceAuthorRegion,
  });
})(globalThis);
